{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C09"],
      "claim": "Camellianin B, a flavone glycoside, was detected in rat brain after intragastric administration of camellianin A, directly demonstrating that a polyphenolic glycoside can cross the BBB after systemic absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Cyanidin-3-O-glucoside was observed in rat brain after intravenous administration, showing that an anthocyanin glycoside with high polarity can achieve CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Cyanidin 3-glucoside was detected in human brain vascular endothelium and brain tissue, providing human evidence for BBB crossing by a glycosylated polyphenol.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Intact cyanidin 3-galactoside was found in pig brain, supporting transfer of dietary anthocyanin glycosides across the BBB in a large-animal model.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Chlorogenic acid, rutin, and hyperoside were detected in rat brain after oral administration of E. senticosus extract, indicating that multiple polar polyphenol glycosides reach brain tissue.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "After a blackberry anthocyanin-enriched diet, C3G was the predominant anthocyanin in rat brain and was higher in brain than plasma, indicating meaningful CNS exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Deacetyl asperulosidic acid methyl ester and other iridoid glycosides were detected in rat brain microdialysates and tissue homogenates, confirming that glycosides can penetrate the BBB.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Although the query is a highly polar flavonoid C-glucoside with unfavorable passive-diffusion properties, multiple high-transfer experimental records demonstrate that structurally related polyphenolic glycosides—including flavone, anthocyanin, and iridoid glycosides—are detected in brain after systemic administration. This transferable experimental evidence outweighs the physicochemical prior and supports meaningful CNS access for the query.",
  "evidence_gaps": [
    "No direct quantitative brain-to-plasma ratio or unbound brain concentration is available for the exact luteolin C-glucoside query.",
    "Most supporting records are qualitative brain detection rather than full pharmacokinetic exposure measures such as AUC or Kp,uu.",
    "The contribution of efflux transporters to the query's net brain exposure is not directly quantified."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

